ALTER TABLE public.marketplace_reservations DROP CONSTRAINT IF EXISTS marketplace_reservations_status_check; ALTER TABLE public.marketplace_reservations ADD CONSTRAINT marketplace_reservations_status_check CHECK (status IN ('pending','approved','rejected','accepted','ready','collected','cancelled','declined','expired')); ALTER TABLE public.app_notifications DROP CONSTRAINT IF EXISTS app_notifications_kind_check; ALTER TABLE public.app_notifications ADD CONSTRAINT app_notifications_kind_check CHECK (kind IN ('announcement','maintenance','update','support','reservation'));